-- 414: Original BrillaPrep WASSCE Integrated Science beta questions, part 2 of 8 (sprint 1 batch 001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_414_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_414_guard;
INSERT INTO _migration_414_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_eco_b001_007' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_eco' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A grassland ecosystem traps 50 000 kJ of energy at the producer level. If only about 10% of the energy is transferred to the next trophic level, the energy reaching the primary consumers is approximately:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 500 kJ","B. 50 kJ","C. 45 000 kJ","D. 5 000 kJ"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Energy transferred = 10% of 50 000 kJ = 0.1 × 50 000 = 5 000 kJ. The other 45 000 kJ is lost through respiration, heat, uneaten material and waste.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_eco_b001_007' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_414_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_eco_b001_008' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_eco' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Natural food chains rarely have more than four or five trophic levels mainly because:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Top carnivores are always hunted by humans","B. Most of the energy is lost at each transfer, leaving too little for higher levels","C. Producers stop growing after a certain height","D. Decomposers attack organisms at higher trophic levels"]' AND q.correct_answer IS 'B' AND q.explanation IS 'About 90% of the energy is lost as heat, in respiration and in waste at each level, so after four or five transfers too little energy remains to support a viable population at another level.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_eco_b001_008' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_414_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_mat_b001_001' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_mat' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The best method for obtaining solid salt from seawater is:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Filtration","B. Evaporation","C. Use of a magnet","D. Decantation"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Salt is dissolved in seawater, so it passes through filter paper with the water. Evaporation removes the water and leaves solid salt; magnets and decantation cannot separate dissolved solids.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_mat_b001_001' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_414_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_mat_b001_002' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_mat' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Filtration is the method used to separate:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Two miscible liquids","B. Dissolved salt from water","C. A mixture of two gases","D. An insoluble solid from a liquid"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The pores of filter paper let the liquid and dissolved particles through but trap insoluble solid particles as the residue. Miscible liquids need distillation and dissolved salts need evaporation.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_mat_b001_002' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_414_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_mat_b001_003' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_mat' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a mixture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Air","B. Distilled water","C. Gold","D. Oxygen gas"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Air is a physical mixture of nitrogen, oxygen, carbon dioxide and other gases. Distilled water is a pure compound, while gold and oxygen gas are pure elements.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_mat_b001_003' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_414_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_mat_b001_004' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_mat' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A magnet would be most useful for separating a mixture of:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Salt and sand","B. Ethanol and water","C. Iron filings and sand","D. Oil and water"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Iron is magnetic and sand is not, so a magnet pulls out the filings. Salt and sand need dissolving and filtering; ethanol and water need distillation; oil and water need a separating funnel.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_mat_b001_004' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
